I've added a lot of `trace!` logs in code to check what's exactly going on, and I have some really interesting results.
<details><summary>Modified recv_server_message fn</summary>
That's how modified code looks like:

```rust
    async fn recv_server_message(
        reader: &mut (impl AsyncBufRead + Unpin + Send),
        buffer: &mut String,
    ) -> Result<ServerMessage> {
        let mut content_length = None;
        loop {
            buffer.truncate(0);
            reader.read_line(buffer).await?;
            log::trace!(
                "line: {:?}, trimmed: {:?}, empty: {}",
                buffer.as_bytes(),
                buffer.trim().as_bytes(),
                buffer.trim().is_empty()
            );
            let header = buffer.trim();

            if header.is_empty() {
                log::trace!("breaking the loop");
                break;
            }

            let mut parts = header.split(": ");

            match (parts.next(), parts.next(), parts.next()) {
                (Some("Content-Length"), Some(value), None) => {
                    content_length = Some(value.parse().context("invalid content length")?);
                }
                (Some(_), Some(_), None) => {}
                _ => {
                    return Err(std::io::Error::new(
                        std::io::ErrorKind::Other,
                        "Failed to parse header",
                    )
                    .into());
                }
            }
        }

        log::trace!("before reading content length");
        let content_length = content_length.context("missing content length")?;
        log::trace!("read content length: {}", content_length);

        //TODO: reuse vector
        let mut content = vec![0; content_length];
        log::trace!("created content vector");
        reader.read_exact(&mut content).await?;
        log::trace!("read exact from reader to content: {:?}", content);
        let msg = String::from_utf8(content).context("invalid utf8 from server")?;
        log::trace!("converted content to msg");

        info!("<- {}", msg);

        // try parsing as output (server response) or call (server request)
        let output: serde_json::Result<ServerMessage> = serde_json::from_str(&msg);
        log::trace!("parsed JSON, output: {:?}", output);
        log::trace!("\n\n");

        Ok(output?)
    }
```

